INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-03-31-italy-fatturapa-1-9-1-published', '2026-03-31', '2026-03', 'Italy''s tax authority has published version 1.9.1 of the FatturaPA technical specifications, introducing a new validation check for VAT Groups, expanded accreditation for high-volume transmission channels, and a new tax-exempt coding for sports workers'' income.', '<h3>🇮🇹 Agenzia delle Entrate publishes FatturaPA technical specifications v1.9.1</h3>
<p>The Agenzia delle Entrate has published version 1.9.1 of Italy''s FatturaPA technical specifications — the detailed rulebook governing exactly what the Sistema di Interscambio (SdI) will and won''t accept, on a system that has run a full clearance model, with real-time invoice validation, since 2019. This is a genuinely mature, continuously refined piece of infrastructure rather than a static one-time build: Italy has extended new controls, document types, and sector-specific rules on a rolling basis for years, and this release continues that pattern rather than representing a one-off event.</p>
<p>Three changes stand out. A new validation check (error code 00327) will reject invoices where a VAT Group''s tax code is incorrectly indicated — a genuinely new failure mode for group-structured businesses to plan around. Accreditation for high-volume Web Service and SFTP transmission channels has been expanded, with service providers now able to request up to 300 recipient codes, up from 100 previously — a meaningful capacity increase for larger intermediaries. And a new "ESENZSPORT" coding has been introduced specifically for tax-exempt income invoiced by sports workers, up to €15,000 per year.</p>
<p><strong>What this means for your team:</strong> if your business operates as a VAT Group, this is worth flagging to whoever manages your SdI integration specifically — a correctly-functioning invoice today could start failing under the new VAT Group check once the specification actually takes effect. Service providers and intermediaries handling high transaction volumes should also confirm their accreditation is updated to take advantage of the higher 300-code ceiling, rather than continuing to operate under the old 100-code limit unnecessarily.</p>', 'https://www.agenziaentrate.gov.it/portale/aree-tematiche/fatturazione-elettronica', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-03-31-italy-fatturapa-1-9-1-published', id FROM countries WHERE name_en = 'Italy';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-03-31-italy-fatturapa-1-9-1-published', 'en', 'Agenzia delle Entrate publishes FatturaPA technical specifications v1.9.1', 'Italy''s tax authority has published version 1.9.1 of the FatturaPA technical specifications, introducing a new validation check for VAT Groups, expanded accreditation for high-volume transmission channels, and a new tax-exempt coding for sports workers'' income.', '<h3>🇮🇹 Agenzia delle Entrate publishes FatturaPA technical specifications v1.9.1</h3>
<p>The Agenzia delle Entrate has published version 1.9.1 of Italy''s FatturaPA technical specifications — the detailed rulebook governing exactly what the Sistema di Interscambio (SdI) will and won''t accept, on a system that has run a full clearance model, with real-time invoice validation, since 2019. This is a genuinely mature, continuously refined piece of infrastructure rather than a static one-time build: Italy has extended new controls, document types, and sector-specific rules on a rolling basis for years, and this release continues that pattern rather than representing a one-off event.</p>
<p>Three changes stand out. A new validation check (error code 00327) will reject invoices where a VAT Group''s tax code is incorrectly indicated — a genuinely new failure mode for group-structured businesses to plan around. Accreditation for high-volume Web Service and SFTP transmission channels has been expanded, with service providers now able to request up to 300 recipient codes, up from 100 previously — a meaningful capacity increase for larger intermediaries. And a new "ESENZSPORT" coding has been introduced specifically for tax-exempt income invoiced by sports workers, up to €15,000 per year.</p>
<p><strong>What this means for your team:</strong> if your business operates as a VAT Group, this is worth flagging to whoever manages your SdI integration specifically — a correctly-functioning invoice today could start failing under the new VAT Group check once the specification actually takes effect. Service providers and intermediaries handling high transaction volumes should also confirm their accreditation is updated to take advantage of the higher 300-code ceiling, rather than continuing to operate under the old 100-code limit unnecessarily.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-05-15-italy-fatturapa-1-9-1-effective', '2026-05-15', '2026-05', 'Italy''s updated FatturaPA technical specifications are now in force, meaning SdI will actively reject invoices using deprecated codes or failing the new VAT Group check — worth knowing exactly which error codes to watch for.', '<h3>🇮🇹 FatturaPA v1.9.1 takes effect — here''s what actually gets rejected now</h3>
<p>The technical specifications published in March are now genuinely live: from today, the Sistema di Interscambio applies the updated FatturaPA v1.9.1 rules to every invoice passing through it. Worth remembering what "rejected" actually means in Italy''s clearance model — without a successful validation receipt from SdI, an invoice is legally considered not issued at all, not merely flagged for correction. That''s a materially higher stakes outcome than a soft compliance warning.</p>
<p>A handful of specific rejection codes are worth knowing by name rather than discovering by accident: 00200 (file doesn''t conform to the XSD schema — usually a header still referencing the old specification version), 00305 (invalid or unknown recipient code, often because a customer''s code was deactivated or mistyped), 00400 and 00403 (deprecated Natura or TipoDocumento sub-codes that need mapping to their v1.9.1 replacements), and 00404 (an obsolete payment method code). None of these are exotic edge cases — they''re exactly the kind of thing that surfaces when an ERP or invoicing system hasn''t been updated to match the new specification.</p>
<p><strong>What this means for your team:</strong> if you haven''t already tested a real invoice through your system since the update, do it now rather than waiting to discover a rejection on a live, time-sensitive invoice. Given non-compliance penalties in Italy run as high as 70% of the tax amount with a minimum of €300 per violation, a handful of silently rejected invoices during a busy period is a genuinely costly way to find out your system wasn''t updated.</p>', 'https://www.agenziaentrate.gov.it/portale/aree-tematiche/fatturazione-elettronica', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-05-15-italy-fatturapa-1-9-1-effective', id FROM countries WHERE name_en = 'Italy';
INSERT INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-05-15-italy-fatturapa-1-9-1-effective', 'en', 'FatturaPA v1.9.1 takes effect — here''s what actually gets rejected now', 'Italy''s updated FatturaPA technical specifications are now in force, meaning SdI will actively reject invoices using deprecated codes or failing the new VAT Group check — worth knowing exactly which error codes to watch for.', '<h3>🇮🇹 FatturaPA v1.9.1 takes effect — here''s what actually gets rejected now</h3>
<p>The technical specifications published in March are now genuinely live: from today, the Sistema di Interscambio applies the updated FatturaPA v1.9.1 rules to every invoice passing through it. Worth remembering what "rejected" actually means in Italy''s clearance model — without a successful validation receipt from SdI, an invoice is legally considered not issued at all, not merely flagged for correction. That''s a materially higher stakes outcome than a soft compliance warning.</p>
<p>A handful of specific rejection codes are worth knowing by name rather than discovering by accident: 00200 (file doesn''t conform to the XSD schema — usually a header still referencing the old specification version), 00305 (invalid or unknown recipient code, often because a customer''s code was deactivated or mistyped), 00400 and 00403 (deprecated Natura or TipoDocumento sub-codes that need mapping to their v1.9.1 replacements), and 00404 (an obsolete payment method code). None of these are exotic edge cases — they''re exactly the kind of thing that surfaces when an ERP or invoicing system hasn''t been updated to match the new specification.</p>
<p><strong>What this means for your team:</strong> if you haven''t already tested a real invoice through your system since the update, do it now rather than waiting to discover a rejection on a live, time-sensitive invoice. Given non-compliance penalties in Italy run as high as 70% of the tax amount with a minimum of €300 per violation, a handful of silently rejected invoices during a busy period is a genuinely costly way to find out your system wasn''t updated.</p>');
INSERT INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-06-15-italy-derogation-vida-convergence', '2026-06-15', '2026-06', 'The EU has authorised Italy to keep its mandatory clearance-based e-invoicing system until 31 December 2027 — a derogation window that ends just as the EU''s ViDA cross-border digital reporting rules are set to begin.', '<h3>🇮🇹 Italy''s clearance mandate runs to the end of 2027 — right when EU ViDA cross-border rules begin</h3>
<p>Under EU VAT rules, member states generally can''t require domestic invoices to take a specific electronic form without a special exemption — which is exactly what Italy has held, on a renewed basis, since first mandating e-invoicing for all VAT-registered businesses back in 2019. The current authorisation, formalised via an EU Implementing Decision, runs Italy''s clearance-based SdI system through 31 December 2027. That date isn''t arbitrary: it lines up closely with the EU''s own ViDA framework, under which cross-border digital reporting requirements begin taking effect for all member states.</p>
<p>Practically, this means Italy''s domestic system and the EU-wide ViDA rules are on a genuine collision course, in a good way — rather than Italy needing to unwind a national system it''s spent years refining, the timing suggests an intentional handoff, where SdI''s already-mature infrastructure becomes the foundation for ViDA compliance rather than something to be replaced by it. Italy is frequently cited as a reference model for ViDA precisely because of this: a country that already runs full invoice-level clearance, at scale, with over a decade of iterative technical refinement behind it.</p>
<p><strong>What this means for your team:</strong> if your business trades cross-border into or out of Italy, don''t treat "ViDA compliance" and "Italian SdI compliance" as two separate future projects to plan for separately. Given how closely the derogation''s expiry lines up with ViDA''s own cross-border timeline, the more useful planning assumption is that whatever you build for Italy today likely forms a meaningful part of what you''ll need for EU-wide cross-border reporting later, rather than a system you''ll need to replace wholesale.</p>', 'https://www.agenziaentrate.gov.it/portale/aree-tematiche/fatturazione-elettronica', 1);
INSERT INTO story_countries (story_id, country_id) SELECT '2026-06-15-italy-derogation-vida-convergence', id FROM countries WHERE name_en = 'Italy';
